pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    receive() external payable {}

    function testFuzz_property(address actor, uint256 seed) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        // find a warp target (>= seed) whose draw is 0, i.e. a winning play
        uint256 drawZeroTs = 0;
        for (uint256 t = seed; t < seed + 500; t++) {
            uint256 r = uint256(keccak256(abi.encodePacked(t, block.difficulty, actor))) % 2;
            if (r == 0) { drawZeroTs = t; break; }
        }
        vm.assume(drawZeroTs != 0);

        vm.warp(drawZeroTs);
        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        // Winning draw (0) must empty the pot.
        assertTrue(c.pot() == 0);
    }
}

