pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, uint256 rd, address actor) public {
        // keep the block environment within realistic bounds; keep actor domain wide
        ts = bound(ts, 1, type(uint64).max);
        rd = bound(rd, 1, type(uint64).max);
        vm.assume(actor != address(0));
        vm.assume(uint160(actor) > 10);

        vm.warp(ts);
        vm.roll(rd);

        // a ticket always costs exactly TICKET_AMOUNT (10)
        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        // mirror the contract's pseudo-random draw to classify the play
        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, actor))) % 2;

        // GENERAL RULE: a winning play (draw == 0) always pays out and resets the pot to 0.
        assertTrue(!(random == 0 && c.pot() != 0), "winning play must reset the pot to 0");
    }
}

