        vm.assume(amount == 10); // exact ticket price, otherwise play() legitimately reverts
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        vm.warp(timestamp);
        uint256 draw = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, actor))) % 2;
        vm.assume(draw == 0); // admissible winning plays: the draw is 0

        vm.deal(actor, amount);
        vm.prank(actor);
        c.play{value: amount}();

        // A winning play (draw == 0) must pay out and reset the pot to 0.
        assertTrue(c.pot() == 0);
    }
