pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        vm.warp(ts);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.play{value: 10 ether}();

        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, actor))) % 2;

        // Rule: after play(), pot == 0 iff the (mod-2) random draw is a win; otherwise pot == 10.
        if (random == 0) {
            assertTrue(c.pot() == 0 && actor.balance >= 9 ether);
        } else {
            assertTrue(c.pot() == 10 ether && actor.balance == 0 ether);
        }
    }
}

