pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, address actor) public {
        // actor must be a plain EOA so the 1wei/9wei transfers never fail
        vm.assume(actor != address(0) && actor.code.length == 0);
        vm.assume(actor != address(this));
        vm.warp(ts);

        vm.deal(actor, 10 wei);
        vm.prank(actor);
        bool ok;
        try c.play{value: 10 wei}() { ok = true; } catch { ok = false; }

        uint256 h = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, actor)));
        if (ok && h % 2 != 0) {
            // Reference rule: no win when hash % 2 != 0, so the pot is untouched at 10.
            assertTrue(c.pot() == 10, "loss must keep pot at 10");
        } else {
            assertTrue(true);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint amount) public {
        require(amount == 10);
        require(address(this).balance >= 2 * amount);
        c.play{value: amount}();
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("play()"));
        assert(ok);
    }
}

